# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KIRTASİYE GEREÇLERİNDE TEKİL (مُفْرَد) - İKİL (مُثَنَّى) - ÇOĞUL (جَمْع)</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Müfred (Tekil - 1 Adet)</text>\n  <text x="42" y="100" font-size="11.5" fill="#334155">• قَلَمٌ (Kalemun): Bir kalem</text>\n  <text x="42" y="125" font-size="11.5" fill="#334155">• دَفْتَرٌ (Defterun): Bir defter</text>\n  <text x="42" y="150" font-size="11.5" fill="#334155">• مِسْطَرَةٌ (Mistaratun): Bir cetvel</text>\n  <text x="42" y="175" font-size="11.5" fill="#334155">• حَقِيبَةٌ (Hakîbetun): Bir çanta</text>\n  <text x="42" y="200" font-size="11.5" fill="#334155">• كِتَابٌ (Kitâbun): Bir kitap</text>\n  <text x="130" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">أُرِيدُ قَلَمًا وَاحِدًا (1 kalem istiyorum)</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Müsenna (İkil - 2 Adet: ـَانِ)</text>\n  <text x="262" y="100" font-size="11.5" fill="#334155">• قَلَمَانِ (Kalemâni): İki kalem</text>\n  <text x="262" y="125" font-size="11.5" fill="#334155">• دَفْتَرَانِ (Defterâni): İki defter</text>\n  <text x="262" y="150" font-size="11.5" fill="#334155">• مِسْطَرَتَانِ (Mistaratâni): İki cetvel</text>\n  <text x="262" y="175" font-size="11.5" fill="#334155">• حَقِيبَتَانِ (Hakîbetâni): İki çanta</text>\n  <text x="262" y="200" font-size="11.5" fill="#334155">• كِتَابَانِ (Kitâbâni): İki kitap</text>\n  <text x="350" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">عِنْدِي دَفْتَرَانِ (2 defterim var)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Cemi (Çoğul - 3 ve Fazlası)</text>\n  <text x="482" y="100" font-size="11.5" fill="#334155">• أَقْلَامٌ (Eklâmun): Kalemler</text>\n  <text x="482" y="125" font-size="11.5" fill="#334155">• دَفَاتِرُ (Defâtiru): Defterler</text>\n  <text x="482" y="150" font-size="11.5" fill="#334155">• مَسَاطِرُ (Mesâtiru): Cetveller</text>\n  <text x="482" y="175" font-size="11.5" fill="#334155">• حَقَائِبُ (Hakâibu): Çantalar</text>\n  <text x="482" y="200" font-size="11.5" fill="#334155">• كُتُبٌ (Kütübün): Kitaplar</text>\n  <text x="570" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">عَشَرَةُ أَقْلَامٍ (10 kalem)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KIRTASİYE DİYALOĞU OKUMA VE SORU-CEVAP KALIPLARI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Örnek Kırtasiye Diyaloğu (فِي الْمَكْتَبَةِ)</text>\n  <text x="42" y="98" font-size="11" font-weight="bold" fill="#1e40af">الْبَائِعُ: مَرْحَبًا، أَيَّ خِدْمَةٍ؟</text>\n  <text x="42" y="114" font-size="10.5" fill="#475569">(Satıcı: Merhaba, nasıl yardımcı olabilirim?)</text>\n  <text x="42" y="136" font-size="11" font-weight="bold" fill="#166534">الْمُشْتَرِي: أَنَا بِحَاجَةٍ إِلَى دَفْتَرٍ وَمِمْحَاةٍ، ثُمَّ مِقَصٍّ.</text>\n  <text x="42" y="152" font-size="10.5" fill="#475569">(Müşteri: Defter ve silgiye, sonra makasa ihtiyacım var.)</text>\n  <text x="42" y="174" font-size="11" font-weight="bold" fill="#1e40af">الْبَائِعُ: أَتُفَضِّلُ الدَّفْتَرَ الْكَبِيرَ أَمِ الصَّغِيرَ؟</text>\n  <text x="42" y="190" font-size="10.5" fill="#475569">(Satıcı: Büyük defteri mi yoksa küçüğü mü tercih edersin?)</text>\n  <text x="42" y="212" font-size="11" font-weight="bold" fill="#166534">الْمُشْتَرِي: أُفَضِّلُ الدَّفْتَرَ الْكَبِيرَ، بِكَمْ كُلُّ هٰذَا؟</text>\n  <text x="42" y="228" font-size="10.5" fill="#475569">(Müşteri: Büyük defteri tercih ederim, hepsi kaç lira?)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Metin Çözümleme Soruları ve Bağlaçlar</text>\n  <text x="378" y="98" font-size="11.5" fill="#334155">• أَيْنَ يَدُورُ الْحِوَارُ؟ (Diyalog nerede geçiyor?)</text>\n  <text x="390" y="116" font-size="11" fill="#991b1b">→ يَدُورُ الْحِوَارُ فِي الْمَكْتَبَةِ. (Kırtasiyede geçiyor.)</text>\n  <text x="378" y="140" font-size="11.5" fill="#334155">• مَاذَا يُرِيدُ الْمُشْتَرِي؟ (Müşteri ne istiyor?)</text>\n  <text x="390" y="158" font-size="11" fill="#991b1b">→ يُرِيدُ دَفْتَرًا وَمِمْحَاةً وَمِقَصًّا.</text>\n  <text x="378" y="182" font-size="11.5" fill="#334155">• بِكَمِ الْمَجْمُوعُ؟ (Toplam tutar ne kadar?)</text>\n  <text x="390" y="200" font-size="11" fill="#991b1b">→ الْمَجْمُوعُ خَمْسَ عَشْرَةَ لِيرَةً. (Toplam 15 liradır.)</text>\n  <text x="517" y="225" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Bağlaçlar: وَ (ve) · أَوْ (veya) · أَمْ (yoksa) · ثُمَّ (sonra)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">11-19 ARASI SAYILARLA ALIŞVERİŞ VE TİCARET AHLAKI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sayı Öbekleri (10-19 Arası Örnekler)</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• 10: عَشَرَةُ طُلَّابٍ / عَشَرَةُ أَقْلَامٍ (10 öğrenci / kalem)</text>\n  <text x="44" y="124" font-size="11.5" fill="#334155">• 11: أَحَدَ عَشَرَ طَالِبًا / دَفْتَرًا (11 öğrenci / defter)</text>\n  <text x="44" y="148" font-size="11.5" fill="#334155">• 12: اِثْنَتَا عَشْرَةَ طَالِبَةً / مِسْطَرَةً (12 kız öğrenci / cetvel)</text>\n  <text x="44" y="172" font-size="11.5" fill="#334155">• 13: ثَلَاثَةَ عَشَرَ طَالِبًا (13 erkek öğrenci)</text>\n  <text x="44" y="196" font-size="11.5" fill="#334155">• 13: ثَلَاثَ عَشْرَةَ طَالِبَةً (13 kız öğrenci)</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">كَمْ قَلَمًا تُرِيدُ؟ (Kaç kalem istiyorsun?)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Ticaret Ahlakı ve Yazılı İfade İlkeleri</text>\n  <text x="378" y="102" font-size="11.5" font-weight="bold" fill="#92400e">1. اِنْتَبِهْ لِلْكَيْلِ وَالْمِيزَانِ</text>\n  <text x="388" y="120" font-size="11" fill="#334155">Ölçüye ve tartıya dikkat et! (Hakkaniyet ilkesi)</text>\n  <text x="378" y="148" font-size="11.5" font-weight="bold" fill="#92400e">2. اللّٰهُ لَا يُحِبُّ الْمُطَفِّفِينَ</text>\n  <text x="388" y="166" font-size="11" fill="#334155">Allah ölçü ve tartıda hile yapanları sevmez.</text>\n  <text x="378" y="194" font-size="11.5" font-weight="bold" fill="#92400e">3. الْكَاسِبُ حَبِيبُ اللّٰهِ</text>\n  <text x="388" y="212" font-size="11" fill="#334155">Helalinden çalışan ve kazanan Allah\'ın dostudur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
